data.query:
query GetOeeConfig {
  setting(where: { id: { _eq: "Timezone" } }) {
    edges {
      node {
        defaultValue
      }
    }
  }
  workcenter(where: { isActive: { _eq: true } }, first: 1000) {
    edges {
      node {
        scheduleGroupId
        _aggregate {
          id {
            uniqueValues
          }
        }
      }
    }
  }
}

