  /* Extract timezone */
  $timezone := setting.edges[0].node.defaultValue ? setting.edges[0].node.defaultValue : $momentTzGuess();
  
  /* Calculate tomorrow's boundaries in local timezone, then convert to UTC */
  $now := $moment().tz($timezone);
  $tomorrowLocal := $now.clone().add(1, 'days').startOf('day'); /* Tomorrow 00:00:00 in local tz */
  $tomorrowEndLocal := $tomorrowLocal.clone().add(1, 'day').startOf('day'); /* Day after tomorrow 00:00:00 in local tz (exclusive end) */
  
  /* Convert to UTC for getTimeline (these are the UTC timestamps representing local day boundaries) */
  $tomorrow := $tomorrowLocal.clone().utc();
  $tomorrowEnd := $tomorrowEndLocal.clone().utc();
  
  /* For each scheduleGroupId group */
  workcenter.edges.node.(
    $scheduleGroupId := scheduleGroupId;
    $workcenterIds := _aggregate.id.uniqueValues;  /* Use IDs instead of codes */
    $timeline := $scheduleGroup($scheduleGroupId).getTimeline($tomorrow, $tomorrowEnd, { "inclusive": true });
    
    {
      "scheduleGroupId": $scheduleGroupId,
      "workcenters": $workcenterIds,  /* Array of workcenter IDs */
      "timezone": $timezone,
      "tomorrowStart": $tomorrow.format(),
      "tomorrowEnd": $tomorrowEnd.format(),
      "tomorrowDate": $tomorrowLocal.format("YYYY-MM-DD"),
      "tomorrowDayOfWeek": ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"][$tomorrowLocal.day()],
      "timeline": $timeline
    }
  )
)

'use strict';

// ═══════════════════════════════════════════════════════════════════════
// OEE HOURLY RECORD GENERATOR
// ═══════════════════════════════════════════════════════════════════════
// Input: Schedule group object with workcenters (IDs), timeline, and timezone
// Output: Array of OeeHourly records (24 per workcenter)
// ═══════════════════════════════════════════════════════════════════════

// Input is the schedule group object directly
const scheduleGroup = $;

// Validate input
if (!scheduleGroup || !scheduleGroup.workcenters || !scheduleGroup.timeline) {
  console.error('Invalid input - missing required fields');
  console.error('Input:', JSON.stringify($, null, 2));
  return [];
}

const { scheduleGroupId, workcenters, timezone, tomorrowStart, tomorrowEnd, timeline } = scheduleGroup;

console.log('Processing scheduleGroup: ' + scheduleGroupId);
console.log('Workcenters: ' + workcenters.length);
console.log('Timezone: ' + timezone);
console.log('Timeline events: ' + timeline.length);

// Parse tomorrow's boundaries (midnight to midnight in local time, expressed in UTC)
const dayStart = $moment(tomorrowStart).utc();
const dayEnd = $moment(tomorrowEnd).utc();

console.log('Tomorrow boundaries (UTC): ' + dayStart.toISOString() + ' to ' + dayEnd.toISOString());

// Constants
const ONE_HOUR_MS = 3600000; // 60 minutes in milliseconds
const ONE_MINUTE_MS = 60000;

// ═══════════════════════════════════════════════════════════════════════
// GENERATE OEE HOURLY RECORDS
// ═══════════════════════════════════════════════════════════════════════
const allRecords = [];

// For each workcenter, generate EXACTLY 24 hourly records (one for each hour of tomorrow)
workcenters.forEach((workcenterId, wcIndex) => {
  // Validation: Ensure workcenterId exists
  if (!workcenterId || workcenterId === null || workcenterId === '') {
    console.error('Skipping null/empty workcenterId at index ' + wcIndex);
    return;
  }
  
  for (let dayHour = 0; dayHour < 24; dayHour++) {
    // Create exact hour boundaries - periods run from :00 to :00 (e.g., 05:00 to 06:00)
    const hourStart = dayStart.clone().add(dayHour, 'hours');
    const hourEnd = hourStart.clone().add(1, 'hour');
    
    // Verify we're still within tomorrow's boundaries
    if (hourStart.isSameOrAfter(dayEnd)) {
      console.error('ERROR: hourStart ' + hourStart.toISOString() + ' is beyond tomorrow end ' + dayEnd.toISOString());
      continue;
    }
    
    // Debug first few hours of first workcenter
    if (dayHour < 3 && wcIndex === 0) {
      console.log('DayHour ' + dayHour + ': ' + hourStart.toISOString() + ' to ' + hourEnd.toISOString());
      console.log('Using workcenter ID: ' + workcenterId);
    }
    
    // Find timeline events that overlap with THIS SPECIFIC HOUR
    const overlappingEvents = timeline.filter(event => {
      const eventStart = $moment(event.range.start).utc();
      const eventEnd = $moment(event.range.end).utc();
      
      // Does the event overlap with this hour?
      const overlaps = hourStart.isBefore(eventEnd) && hourEnd.isAfter(eventStart);
      
      if (dayHour < 3 && wcIndex === 0) {
        console.log('  Event ' + event.scheduleId + ': ' + eventStart.toISOString() + ' to ' + eventEnd.toISOString() + ', overlaps: ' + overlaps);
      }
      
      return overlaps;
    });
    
    if (overlappingEvents.length === 0) {
      // ═══════════════════════════════════════════════════════════════
      // NO SCHEDULE: Full hour of planned downtime
      // ═══════════════════════════════════════════════════════════════
      const id = workcenterId + '-0-' + hourStart.toISOString();
      allRecords.push({
        id: id,
        workcenterId: workcenterId,
        scheduleId: null,
        dayHour: dayHour,
        shiftHour: 0,
        shift: 'No Schedule Defined',
        periodStartAt: hourStart.toISOString(),
        periodEndAt: hourEnd.toISOString(),
        scheduleHourStartAt: hourStart.toISOString(),
        scheduleHourEndAt: hourEnd.toISOString(),
        scheduledTime: 0,                      // ✅ NO scheduled time when no schedule
        plannedMinutes: 0,                     // Always 0
        plannedDowntimeMinutes: ONE_HOUR_MS    // ✅ Full hour = planned downtime
      });
      
      if (dayHour < 3 && wcIndex === 0) {
        console.log('  No schedule: scheduledTime=0, plannedDowntime=3600000ms (full hour)');
      }
    } else {
      // Process each overlapping event
      overlappingEvents.forEach(event => {
        const scheduleId = event.scheduleId;
        const isException = event.exception === true;
        
        // Get THIS event's actual start time (not just the hour)
        const eventStartUTC = $moment(event.range.start).utc();
        const eventEndUTC = $moment(event.range.end).utc();
        
        // Calculate shiftHour based on THIS specific event's start time
        const hoursFromEventStart = hourStart.diff(eventStartUTC, 'hours');
        const shiftHour = hoursFromEventStart + 1; // 1-indexed
        
        if (dayHour < 3 && wcIndex === 0) {
          console.log('  Event starts: ' + eventStartUTC.toISOString());
          console.log('  Current hour: ' + hourStart.toISOString());
          console.log('  Hours elapsed: ' + hoursFromEventStart + ', shiftHour: ' + shiftHour);
          console.log('  Is exception: ' + isException);
        }
        
        // CRITICAL: Clip event boundaries to THIS HOUR and TOMORROW'S boundaries
        const segmentStart = $momentMax([hourStart, eventStartUTC]);
        const segmentEnd = $momentMin([hourEnd, eventEndUTC, dayEnd]);
        
        // Calculate milliseconds for the segment
        const segmentMs = segmentEnd.diff(segmentStart, 'milliseconds');
        const segmentMinutes = segmentEnd.diff(segmentStart, 'minutes');
        
        // Calculate remainder of the hour (time outside the segment)
        const remainderMs = ONE_HOUR_MS - segmentMs;
        
        // Verify segment is within tomorrow's boundaries
        if (segmentStart.isBefore(dayStart) || segmentStart.isSameOrAfter(dayEnd)) {
          console.error('ERROR: segmentStart ' + segmentStart.toISOString() + ' is outside tomorrow boundaries');
        }
        
        const id = workcenterId + '-' + shiftHour + '-' + segmentStart.toISOString();
        
        // ═══════════════════════════════════════════════════════════════
        // SCHEDULED EVENT
        // ═══════════════════════════════════════════════════════════════
        const record = {
          id: id,
          workcenterId: workcenterId,
          scheduleId: scheduleId,
          dayHour: dayHour,
          shiftHour: shiftHour,
          shift: isException ? 'Exception' : scheduleId,
          periodStartAt: hourStart.toISOString(),
          periodEndAt: hourEnd.toISOString(),
          scheduleHourStartAt: segmentStart.toISOString(),
          scheduleHourEndAt: segmentEnd.toISOString(),
          scheduledTime: ONE_HOUR_MS,  // ✅ Always full hour when there IS a schedule
          plannedMinutes: 0             // Always 0 (calculated later from actual data)
        };
        
        // Calculate plannedDowntimeMinutes based on type
        if (isException) {
          // EXCECustomer-DON: The exception time itself is planned downtime
          record.plannedDowntimeMinutes = segmentMs;
          if (dayHour < 3 && wcIndex === 0) {
            console.log('  Exception event: scheduledTime=3600000, plannedDowntime=' + segmentMs + 'ms');
          }
        } else {
          // NORMAL SCHEDULE: Only the remainder (if any) is planned downtime
          record.plannedDowntimeMinutes = remainderMs;
          if (dayHour < 3 && wcIndex === 0) {
            console.log('  Normal schedule: scheduledTime=3600000, plannedDowntime=' + remainderMs + 'ms (remainder)');
          }
        }
        
        // Add isPartialHour flag if less than 60 minutes scheduled
        if (segmentMinutes < 60 && segmentMinutes > 0) {
          record.isPartialHour = true;
        }
        
        allRecords.push(record);
      });
    }
  }
});

console.log('═══════════════════════════════════════════════════════════');
console.log('Generated ' + allRecords.length + ' OeeHourly records total');
console.log('Workcenters processed: ' + workcenters.length);
console.log('Expected records: ' + (workcenters.length * 24));
console.log('Records per workcenter: ' + (allRecords.length / workcenters.length).toFixed(1));
console.log('═══════════════════════════════════════════════════════════');

if (allRecords.length > 0) {
  console.log('Sample NO SCHEDULE record:');
  const noScheduleRecord = allRecords.find(r => r.scheduleId === null);
  if (noScheduleRecord) {
    console.log(JSON.stringify(noScheduleRecord, null, 2));
  }
  
  console.log('Sample SCHEDULED record:');
  const scheduledRecord = allRecords.find(r => r.scheduleId !== null);
  if (scheduledRecord) {
    console.log(JSON.stringify(scheduledRecord, null, 2));
  }
}

// Final validation
const nullWorkcenters = allRecords.filter(r => !r.workcenterId);
if (nullWorkcenters.length > 0) {
  console.error('CRITICAL: ' + nullWorkcenters.length + ' records have null workcenterId!');
}

// Validation: Check scheduledTime logic
const invalidScheduledTime = allRecords.filter(r => {
  if (r.scheduleId === null && r.scheduledTime !== 0) {
    return true; // No schedule but scheduledTime > 0
  }
  if (r.scheduleId !== null && r.scheduledTime === 0) {
    return true; // Has schedule but scheduledTime = 0
  }
  return false;
});

if (invalidScheduledTime.length > 0) {
  console.error('CRITICAL: ' + invalidScheduledTime.length + ' records have invalid scheduledTime!');
  console.error('Sample invalid record:', JSON.stringify(invalidScheduledTime[0], null, 2));
}

return allRecords;

